#!/bin/bash
# promptfoo-style custom provider: shells out to the real `opencode` CLI,
# using this repo's actual generated .opencode/agents/orchestrator.md as the
# agent under test. Tests whether agent-meta's GENERATED Opencode routing
# table (not a description of it) produces correct delegation decisions in a
# real Opencode session.
#
# --- Phase-2 spike findings (verified, see
# docs/concepts/planned/orchestrator-routing-test-suite.md Sec. 5) ---
#
# 1. `opencode run --agent <name>` only works for agents with `mode: primary`
#    in their frontmatter. Every agent generated by sync.py under
#    .opencode/agents/*.md (including orchestrator.md) has `mode: subagent`.
#    `opencode agent list` shows exactly one primary agent: `build`. Calling
#    `--agent orchestrator` silently falls back to the generic `build` agent
#    (with a stderr warning) -- that does NOT exercise the real orchestrator
#    persona/routing table, and `build` has very broad permissions
#    ("*": allow for most actions), which is unsuitable for a one-word
#    classification task. Workaround (below): copy orchestrator.md into an
#    isolated dir with `mode: primary` and load it as a primary agent.
# 2. Model: `opencode/deepseek-v4-flash-free` had an unstable/unreachable
#    upstream during the spike (`AI_APICallError: Upstream request failed:
#    Endpoint is unavailable`, retries up to minutes). Use the paid
#    `opencode-go/deepseek-v4-flash` instead (stable, fast, ~$0.0007/call).
# 3. `--format json` streams NDJSON (one JSON object per line). The model
#    answer is in the `part.text` field of the LAST event with
#    `"type":"text"` (in case reasoning produces earlier text events too).
#
# Isolation: analogous to provider-claude.sh's mktemp-dir strategy, but
# Opencode has no --system-prompt-file equivalent -- `--agent <name>` must
# resolve to a file under <dir>/.opencode/agents/. We build an ephemeral
# directory containing only a `mode: primary` copy of the real
# orchestrator.md (read fresh from the repo on every call, never hardcoded,
# so template drift is picked up automatically) and run `opencode run`
# there via `--dir`. This also prevents AGENTS.md/repo-context leakage into
# the test, same rationale as provider-claude.sh's isolation.
set -uo pipefail
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PROMPT="$1"

SRC_AGENT="$REPO_ROOT/.opencode/agents/orchestrator.md"
if [[ ! -f "$SRC_AGENT" ]]; then
  echo "provider-opencode: source agent file not found: $SRC_AGENT" >&2
  exit 0
fi

RUN_DIR="$(mktemp -d)"
trap 'rm -rf "$RUN_DIR"' EXIT

mkdir -p "$RUN_DIR/.opencode/agents"
sed 's/^mode: subagent$/mode: primary/' "$SRC_AGENT" > "$RUN_DIR/.opencode/agents/orchestrator.md"

# The whole test's validity rests on this substitution actually landing --
# if sync.py ever changes the frontmatter format (whitespace, casing, no
# space after the colon), the sed silently no-ops and `opencode run` falls
# back to the generic `build` agent with only a stderr warning (swallowed
# below and in run_eval.sh), which would show up as a mysterious all-FAIL
# run rather than a loud infra error. Assert it instead.
if ! grep -q '^mode: primary$' "$RUN_DIR/.opencode/agents/orchestrator.md"; then
  echo "provider-opencode: mode:primary substitution failed on $SRC_AGENT (frontmatter format drift?)" >&2
  exit 2
fi

MODEL="${OPENCODE_ROUTING_EVAL_MODEL:-opencode-go/deepseek-v4-flash}"

# `opencode run` spawns a detached `opencode serve` background process
# (PPID 1, ~600MB RSS) that does NOT exit when the run completes -- verified
# during the spike. Left unchecked, a full 45-case x repeat=3 sweep would
# leak ~135 such processes (tens of GB of RAM). Snapshot server PIDs before
# and after the call, and kill only the ones that appeared during this
# invocation (leaves any pre-existing, unrelated opencode servers alone).
pids_before="$(pgrep -x opencode 2>/dev/null || true)"

raw_output="$(
  cd "$RUN_DIR" && timeout 90 opencode run "$PROMPT" \
    --agent orchestrator \
    --format json \
    --model "$MODEL" \
    --dir "$RUN_DIR" 2>/dev/null
)"

pids_after="$(pgrep -x opencode 2>/dev/null || true)"
new_pids="$(comm -13 <(echo "$pids_before" | sort) <(echo "$pids_after" | sort))"
if [[ -n "$new_pids" ]]; then
  # shellcheck disable=SC2086
  kill $new_pids 2>/dev/null || true
fi

if [[ -z "$raw_output" ]]; then
  # No output at all (timeout, crash, upstream error) -- emit nothing so
  # run_eval.sh's normalization produces an empty (non-matching) actual
  # value rather than aborting the whole run.
  exit 0
fi

printf '%s\n' "$raw_output" | python3 -c '
import json
import sys

answer = None
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        event = json.loads(line)
    except json.JSONDecodeError:
        continue
    if event.get("type") == "text":
        text = event.get("part", {}).get("text")
        if text is not None:
            answer = text

print((answer or "").strip())
'
